function pick(xml, tag) {
  const m = xml.match(new RegExp('<' + tag + '>([\\s\\S]*?)</' + tag + '>'));
  return m ? m[1].trim() : '';
}
async function fetchRtms(lawd, ymd, rows) {
  const url = 'https://apis.data.go.kr/1613000/RTMSDataSvcAptTradeDev/getRTMSDataSvcAptTradeDev'
    + '?serviceKey=' + DGK + '&LAWD_CD=' + encodeURIComponent(lawd)
    + '&DEAL_YMD=' + encodeURIComponent(ymd) + '&numOfRows=' + rows + '&pageNo=1';
  let last = null;
  for (let i = 0; i < 3; i++) {
    try {
      const xml = await httpGet(url, 25000);
      if (!['00','000'].includes(pick(xml, 'resultCode'))) { last = new Error('resultCode=' + pick(xml, 'resultCode')); continue; }
      const items = [];
      const blocks = xml.split('<item>').slice(1);
      for (const b of blocks) {
        const body = b.split('</item>')[0];
        items.push({
          apt: pick(body, 'aptNm'), dong: pick(body, 'umdNm'),
          area: parseFloat(pick(body, 'excluUseAr')) || 0,
          price: parseInt(String(pick(body, 'dealAmount')).replace(/[^0-9]/g, ''), 10) || 0,
          date: pick(body, 'dealYear') + '.' + pick(body, 'dealMonth') + '.' + pick(body, 'dealDay'),
          floor: pick(body, 'floor')
        });
      }
      return { rows: items, total: parseInt(pick(xml, 'totalCount'), 10) || items.length };
    } catch (e) { last = e; }
  }
  return { rows: [], total: 0, fetchError: String(last && last.message || last) };
}
const out = [];
for (const it of $input.all()) {
  const p = it.json;
  const r = await fetchRtms(p.lawd_cd, p.deal_ymd, 100);
  let rows = r.rows;
  if (p.apt) rows = rows.filter(x => (x.apt || '').includes(p.apt));
  const prices = rows.map(x => x.price).filter(x => x > 0).sort((a, b) => a - b);
  const sum = prices.reduce((a, b) => a + b, 0);
  const stats = {
    count: rows.length, total: r.total,
    avg: prices.length ? Math.round(sum / prices.length) : 0,
    median: prices.length ? prices[Math.floor(prices.length / 2)] : 0,
    min: prices.length ? prices[0] : 0, max: prices.length ? prices[prices.length - 1] : 0,
    fetchError: r.fetchError || ''
  };
  out.push({ json: { ...p, rows: rows.slice(0, 60), stats } });
}
return out;

