const SYS_V1 = '너는 한국 아파트 실거래 브리핑 작성자다. 주어진 통계와 표본을 읽고 거래동향을 한 단락으로 요약하라. 숫자를 지어내지 마라. 전망이나 추천을 덧붙이지 마라. 표본이 0건이면 자료 없음이라 쓰고 끝내라.';
const SYS_V2 = '너는 한국 아파트 실거래 브리핑 작성자다. 순서대로 쓴다. (1) 핵심 한 줄: 평균가·중앙값·거래건수. (2) 표본 0건이면 자료 없음이라 쓰고 가능한 원인 한 줄. (3) 5건 이상이면 급등·급매 주목 매물을 각 한 줄. 숫자는 주어진 것만 쓰고 과장 표현 금지.';
async function chat(sys, user) {
  const r = await httpRaw('POST', 'https://api.openai.com/v1/chat/completions',
    { Authorization: 'Bearer ' + OPENAI, 'Content-Type': 'application/json' },
    JSON.stringify({ model: 'gpt-4o-mini', temperature: 0.2, max_tokens: 600,
      messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] }), 60000);
  if (r.status !== 200) throw new Error('openai HTTP' + r.status + ' ' + r.body.slice(0, 200));
  const j = JSON.parse(r.body);
  return { text: j.choices[0].message.content, usage: j.usage };
}
