async function tool_fetch_month(lawd, ymd) {
  const url = 'https://apis.data.go.kr/1613000/RTMSDataSvcAptTradeDev/getRTMSDataSvcAptTradeDev'
    + '?serviceKey=' + DGK + '&LAWD_CD=' + encodeURIComponent(lawd)
    + '&DEAL_YMD=' + encodeURIComponent(ymd) + '&numOfRows=30&pageNo=1';
  const xml = await httpGet(url, 25000);
  return 'resultCode=' + pick(xml, 'resultCode') + ', items~' + (xml.split('<item>').length - 1);
}
