  const arr = await httpJson('GET',
    SB_URL + '/rest/v1/agent_reports?region=like.' + encodeURIComponent(lawd) + '/*&status=eq.approved&order=created_at.desc&limit=2&select=region,final,created_at',
    { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY }, undefined, 15000);
  if (!arr.length) return '승인된 과거 리포트 없음';
  return arr.map(x => '[' + x.created_at + '] ' + String(x.final || '').slice(0, 300)).join('\n---\n');
}
const out = [];
for (const it of $input.all()) {
  const p = it.json;
  const t0 = Date.now();
  const trace = [];
  let usage = { prompt_tokens: 0, completion_tokens: 0 };
  const sys = p.prompt_version === 'v2' ? SYS_V2 : SYS_V1;
  const brief = '지역=' + p.lawd_cd + ' 연월=' + p.deal_ymd + (p.apt ? ' 단지=' + p.apt : '')
    + '\n[통계] ' + JSON.stringify(p.stats)
    + '\n[표본상위5] ' + JSON.stringify((p.rows || []).slice(0, 5))
    + (p.memo ? '\n[메모] ' + p.memo : '');
    + '\n[통계] ' + JSON.stringify(p.stats)
    + '\n[표본상위5] ' + JSON.stringify((p.rows || []).slice(0, 5))
    + (p.memo ? '\n[메모] ' + p.memo : '');
  let draft = '';
  for (let i = 0; i < 8; i++) {
    const ask = i === 0
      ? brief + '\n\n위 자료로 브리핑 초안을 써라. 전월 비교가 필요하면 TOOL:fetch_month:LAWD,YYYYMM 로 조회하고, 과거 리포트가 필요하면 TOOL:recall_reports 로 조회하라. 도구가 필요 없으면 바로 초안을 써라.'
      : '관찰: ' + lastObs + '\n위 결과를 반영해 다음 행동을 정하라. 초안이 완성됐으면 초안만 출력하고 TOOL을 부르지 마라.';
    const r = await chat(sys, ask);
    usage.prompt_tokens += (r.usage && r.usage.prompt_tokens) || 0;
    usage.completion_tokens += (r.usage && r.usage.completion_tokens) || 0;
    const line = (r.text || '').trim().split('\n')[0] || '';
    let lastObs = '';
    if (/^TOOL:fetch_month:(\S+)/.test(line)) {
      const parts = (line.match(/^TOOL:fetch_month:(\S+)/)[1] || '').split(',');
      const a = parts[0], b = parts[1];
      lastObs = await tool_fetch_month(a || p.lawd_cd, b || p.deal_ymd);
      trace.push({ i, tool: 'fetch_month', obs: String(lastObs).slice(0, 200) });
      continue;
    }
    if (/^TOOL:recall_reports/.test(line)) {
      lastObs = await tool_recall(p.lawd_cd);
      trace.push({ i, tool: 'recall_reports', obs: String(lastObs).slice(0, 200) });
      continue;
    }
    draft = r.text;
    trace.push({ i, tool: 'finish' });
    break;
  }
  if (!draft) draft = '(초안 생성 실패 — 통계만 전달)';
  const ms = Date.now() - t0;
  const costKrw = Math.round(((usage.prompt_tokens * 0.15 + usage.completion_tokens * 0.6) / 1e6) * 1400 * 100) / 100;
  out.push({ json: { ...p, draft, usage, trace, ms, costKrw } });
}
return out;

